CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT NOT NULL UNIQUE,nom TEXT NOT NULL,pw_hash TEXT NOT NULL,salt TEXT NOT NULL,accord TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS user_data(user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,k TEXT NOT NULL,v TEXT NOT NULL,updated INTEGER NOT NULL,PRIMARY KEY(user_id,k));
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS attempts(email TEXT PRIMARY KEY,n INTEGER NOT NULL,until INTEGER NOT NULL);
